import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    static String readLine() throws IOException {
        return br.readLine();
    }

    static int readInt() throws IOException {
        return Integer.parseInt(readLine());
    }

    static long readLong() throws IOException {
        return Long.parseLong(readLine());
    }

    static List<Integer> readInts() throws IOException {
        String[] parts = readLine().split(" ");
        List<Integer> result = new ArrayList<>();
        for (String p : parts) result.add(Integer.parseInt(p));
        return result;
    }

    static List<Long> readLongs() throws IOException {
        String[] parts = readLine().split(" ");
        List<Long> result = new ArrayList<>();
        for (String p : parts) result.add(Long.parseLong(p));
        return result;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        System.out.print(3 * n / 2);
    }
}
